# -*- coding: utf-8 -*-
import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.ticker as ticker
from matplotlib.colors import LogNorm
from scipy.stats import pearsonr

# ==========================================
# 1. Configuration & Paths
# ==========================================
output_dir = "/data/China_mapping/compare_other/plot/"
os.makedirs(output_dir, exist_ok=True)

# Point to the single master CSV generated by the previous script
master_csv = os.path.join(
    output_dir,
    "All_Products_Comparison_Sampled_1M.csv"
)

output_tif = os.path.join(
    output_dir,
    "TopJournal_6_Parameters_Comparison.tif"
)

output_png = os.path.join(
    output_dir,
    "TopJournal_6_Parameters_Comparison.png"
)

# Explicitly define CSV column names and displayed axis labels
param_configs = [
    {
        "x_name": "Cai AGB",
        "y_name": "Our AGB",
        "x_label": "Cai AGB",
        "y_label": "Our AGB",
        "lat_name": "AGB",
        "unit": "Mg ha$^{-1}$",
        "label": "a",
        "bins": 100
    },
    {
        "x_name": "CCI AGB",
        "y_name": "Our AGB",
        "x_label": "CCI AGB",
        "y_label": "Our AGB",
        "lat_name": "AGB",
        "unit": "Mg ha$^{-1}$",
        "label": "b",
        "bins": 100
    },
    {
        "x_name": "Cheng AGE",
        "y_name": "Our AGE",
        "x_label": "Cheng Age",
        "y_label": "Our Age",
        "lat_name": "Age",
        "unit": "years",
        "label": "c",
        "bins": 100
    },
    {
        "x_name": "Bonan AGE",
        "y_name": "Our AGE",
        "x_label": "Bonan Age",
        "y_label": "Our Age",
        "lat_name": "Age",
        "unit": "years",
        "label": "d",
        "bins": 100
    },
    {
        "x_name": "Cheng H",
        "y_name": "Our H",
        "x_label": "Cheng Height",
        "y_label": "Our Height",
        "lat_name": "Height",
        "unit": "m",
        "label": "e",
        "bins": 80
    },
    {
        "x_name": "Lang H",
        "y_name": "Our H",
        "x_label": "Lang Height",
        "y_label": "Our Height",
        "lat_name": "Height",
        "unit": "m",
        "label": "f",
        "bins": 80
    }
]

# ==========================================
# 2. Global Plotting Setup
# ==========================================
plt.rcParams.update({
    "font.size": 15,
    "font.family": "sans-serif",
    "font.sans-serif": ["Arial", "Helvetica", "sans-serif"],
    "axes.linewidth": 1.5,
    "lines.linewidth": 2.0,
    "pdf.fonttype": 42,
    "ps.fonttype": 42,
    "mathtext.default": "regular"
})

COLOR_REF = "#737373"
COLOR_OUR = "#E31A1C"

# Use GridSpec to create a custom layout
fig = plt.figure(figsize=(21, 14))

gs = fig.add_gridspec(
    3,
    5,
    width_ratios=[1.15, 1.0, -0.1, 1.15, 1.0],
    hspace=0.32,
    wspace=0.32
)

# Extract axes pairs into a list for easy iteration
axes_pairs = []

for row in range(3):
    axes_pairs.append(
        (
            fig.add_subplot(gs[row, 0]),
            fig.add_subplot(gs[row, 1])
        )
    )

    axes_pairs.append(
        (
            fig.add_subplot(gs[row, 3]),
            fig.add_subplot(gs[row, 4])
        )
    )

# ==========================================
# 3. Processing and Plotting Loop
# ==========================================
print(f"Loading master CSV into memory: {master_csv}...")

df_master = pd.read_csv(master_csv)

for i, config in enumerate(param_configs):
    ax_scatter, ax_lat = axes_pairs[i]

    print(
        f"Processing [{config['x_name']}] "
        f"vs [{config['y_name']}]..."
    )

    # ---------------- Read Data ----------------
    ref_col = config["x_name"]
    our_col = config["y_name"]

    df_pair = df_master[
        [ref_col, our_col, "Lat"]
    ].dropna()

    ref_valid = df_pair[ref_col].values
    our_valid = df_pair[our_col].values
    lat_valid = df_pair["Lat"].values

    # Statistical metrics
    r_value, _ = pearsonr(ref_valid, our_valid)
    bias_value = np.mean(our_valid - ref_valid)

    rmse_value = np.sqrt(
        np.mean((our_valid - ref_valid) ** 2)
    )

    ref_mean = np.mean(ref_valid)
    our_mean = np.mean(our_valid)

    min_val = 0

    max_val = max(
        np.percentile(ref_valid, 99.5),
        np.percentile(our_valid, 99.5)
    )

    # ==========================================
    # Panel 1: Premium Density Scatter Plot
    # ==========================================
    ax_scatter.set_facecolor("#ffffff")

    h = ax_scatter.hist2d(
        ref_valid,
        our_valid,
        bins=config["bins"],
        range=[
            [min_val, max_val],
            [min_val, max_val]
        ],
        cmap="YlGnBu",
        cmin=1,
        norm=LogNorm()
    )

    # 1:1 line
    ax_scatter.plot(
        [min_val, max_val],
        [min_val, max_val],
        color="#999999",
        linestyle="--",
        linewidth=1.5,
        zorder=3,
        dashes=(5, 4)
    )

    # Regression line
    m, b = np.polyfit(ref_valid, our_valid, 1)

    regression_x = np.array([min_val, max_val])

    ax_scatter.plot(
        regression_x,
        m * regression_x + b,
        color=COLOR_OUR,
        linewidth=2.0,
        zorder=4
    )

    # Colorbar configuration
    cbar = fig.colorbar(
        h[3],
        ax=ax_scatter,
        shrink=0.85,
        aspect=25,
        pad=0.03
    )

    cbar.set_label(
        "Count (Log Scale)",
        fontsize=13,
        labelpad=6
    )

    cbar.ax.tick_params(
        direction="in",
        length=4,
        labelsize=12
    )

    cbar.outline.set_linewidth(0.8)
    cbar.minorticks_off()

    # Statistics box
    textstr = (
        f"R = {r_value:.2f}\n"
        f"RMSE = {rmse_value:.2f}\n"
        f"Bias = {bias_value:.2f}\n"
        f"Ref Mean = {ref_mean:.2f}\n"
        f"Our Mean = {our_mean:.2f}"
    )

    props = {
        "boxstyle": "square,pad=0.8",
        "facecolor": "white",
        "alpha": 0.5,
        "edgecolor": "#cccccc",
        "linewidth": 0.8
    }

    ax_scatter.text(
        0.04,
        0.96,
        textstr,
        transform=ax_scatter.transAxes,
        fontsize=14,
        verticalalignment="top",
        bbox=props,
        zorder=5,
        color="black",
        fontweight="normal"
    )

    # Axis settings
    ax_scatter.set_xlabel(
        f"{config['x_label']} ({config['unit']})"
    )

    ax_scatter.set_ylabel(
        f"{config['y_label']} ({config['unit']})"
    )

    ax_scatter.set_xlim(min_val, max_val)
    ax_scatter.set_ylim(min_val, max_val)
    ax_scatter.set_aspect("equal", adjustable="box")

    # Panel label
    ax_scatter.annotate(
        config["label"],
        xy=(0, 1),
        xycoords="axes fraction",
        xytext=(-45, 10),
        textcoords="offset points",
        fontsize=24,
        fontweight="bold",
        fontfamily="Arial",
        ha="center",
        va="bottom"
    )

    # ==========================================
    # Panel 2: Latitudinal Distribution
    # ==========================================
    lat_bins = np.arange(
        np.floor(lat_valid.min()),
        np.ceil(lat_valid.max()) + 0.5,
        0.5
    )

    lat_centers = (
        lat_bins[:-1] + lat_bins[1:]
    ) / 2

    mean_ref = np.zeros_like(lat_centers)
    std_ref = np.zeros_like(lat_centers)
    mean_our = np.zeros_like(lat_centers)
    std_our = np.zeros_like(lat_centers)

    for j in range(len(lat_bins) - 1):
        mask = (
            (lat_valid >= lat_bins[j])
            & (lat_valid < lat_bins[j + 1])
        )

        if np.sum(mask) > 10:
            mean_ref[j] = np.mean(ref_valid[mask])
            std_ref[j] = np.std(ref_valid[mask])

            mean_our[j] = np.mean(our_valid[mask])
            std_our[j] = np.std(our_valid[mask])

        else:
            mean_ref[j] = np.nan
            std_ref[j] = np.nan
            mean_our[j] = np.nan
            std_our[j] = np.nan

    df_lat = pd.DataFrame({
        "ref": mean_ref,
        "our": mean_our,
        "ref_s": std_ref,
        "our_s": std_our
    })

    df_lat_smooth = (
        df_lat
        .interpolate()
        .rolling(
            window=3,
            center=True,
            min_periods=1
        )
        .mean()
    )

    # Plot reference product
    ax_lat.plot(
        df_lat_smooth["ref"],
        lat_centers,
        color=COLOR_REF,
        label="Ref",
        linewidth=2.5,
        zorder=4
    )

    ax_lat.fill_betweenx(
        lat_centers,
        df_lat_smooth["ref"] - df_lat_smooth["ref_s"],
        df_lat_smooth["ref"] + df_lat_smooth["ref_s"],
        color=COLOR_REF,
        alpha=0.15,
        edgecolor="none",
        zorder=2
    )

    # Plot our product
    ax_lat.plot(
        df_lat_smooth["our"],
        lat_centers,
        color=COLOR_OUR,
        label="Our",
        linewidth=2.5,
        zorder=5
    )

    ax_lat.fill_betweenx(
        lat_centers,
        df_lat_smooth["our"] - df_lat_smooth["our_s"],
        df_lat_smooth["our"] + df_lat_smooth["our_s"],
        color=COLOR_OUR,
        alpha=0.15,
        edgecolor="none",
        zorder=3
    )

    ax_lat.set_xlabel(
        f"{config['lat_name']} ({config['unit']})"
    )

    ax_lat.set_ylabel(
        "Latitude ($^\\circ$N)"
    )

    # Legend
    ax_lat.legend(
        loc="lower right",
        frameon=True,
        fontsize=14,
        facecolor="white",
        framealpha=0.85,
        edgecolor="#cccccc"
    )

    # ==========================================
    # Universal Axis Formatting
    # ==========================================
    for ax in [ax_scatter, ax_lat]:
        ax.xaxis.set_major_locator(
            ticker.MaxNLocator(
                nbins=6,
                prune="lower"
            )
        )

        ax.yaxis.set_major_locator(
            ticker.MaxNLocator(nbins=6)
        )

        ax.minorticks_off()

        ax.tick_params(
            axis="both",
            which="major",
            length=7,
            width=1.5,
            direction="in",
            top=True,
            right=True
        )

# ==========================================
# 4. Export
# ==========================================
print("Saving high-resolution figures...")

plt.savefig(
    output_tif,
    format="tiff",
    dpi=400,
    pil_kwargs={"compression": "tiff_lzw"},
    bbox_inches="tight"
)

plt.savefig(
    output_png,
    format="png",
    dpi=400,
    bbox_inches="tight"
)

print(
    "Process completed successfully. Files saved to:\n"
    f"1. {output_tif}\n"
    f"2. {output_png}"
)